"""GĐ9.3 Playground page (replaces the one in ui_ls2): the previous prompt/compare/experiment features + tools (catalogue or inline JSON-schema tools, mock or real
read-only results), structured output (JSON schema + validation), images in the human message, saved model configurations (load, save current, compare side by side).
English source strings (Vietnamese through i18n_dict.json). API: app/prompt_lab.py (/api/playground/lab, /api/playground/tools) + /api/model_presets."""
from ui import page
from ui_ls2 import BASE_CSS, HELP_JS

CSS = """<style>.pg{display:grid;grid-template-columns:1fr 1fr;gap:0;border-top:1px solid var(--bd2)}.pg>div{padding:14px 18px;min-width:0}.pg>div+div{border-left:1px solid var(--bd2)}.pgh{display:flex;align-items:center;gap:8px;margin-bottom:10px}.pgh b{font-size:13px}
.nx table td{vertical-align:top}.nx textarea{min-height:54px;font-family:var(--mono);font-size:12px;width:100%}
.pgp{border:1px solid var(--bd2);border-radius:var(--r-lg);padding:12px;margin-top:12px;background:var(--s1)}.pgp textarea{font-family:var(--mono);font-size:12px;width:100%}
.thumbs{display:flex;gap:8px;flex-wrap:wrap;padding:8px 10px;border-top:1px solid var(--bd3)}.thumb{position:relative;width:64px;height:64px;border-radius:var(--r-md);border:1px solid var(--bd2);overflow:hidden;background:var(--s2)}.thumb img{width:100%;height:100%;object-fit:cover}
.thumb button{position:absolute;top:1px;right:1px;height:18px;width:18px;padding:0;border-radius:99px;display:flex;align-items:center;justify-content:center}
.tcard{border:1px solid var(--bd2);border-radius:var(--r-md);padding:8px 10px;margin:8px 0;background:var(--s1)}.tcard pre{margin:6px 0 0;max-height:150px;overflow:auto;font-size:12px;white-space:pre-wrap}.tcard textarea{margin-top:6px}
.stp{white-space:pre-wrap;font-size:13.5px;margin:6px 0}.stp.old{opacity:.6}.errl{color:var(--er);font-size:12px;margin-top:4px}
</style>"""

BODY = """<div class="ph" id="ph"></div><div class="pg">
<div><div class="pgh"><b>Prompts</b><span class="sp"></span><select id="pmodel" style="height:28px"></select></div><div id="msgs"></div><div class="row"><button class="g" id="addm">${plus}Message</button><button class="g" id="adds">Output Schema</button><button class="g" id="addt">Tools</button></div>
<div id="schema" class="pgp" style="display:none"><div class="row"><div class="h4">Output Schema (JSON)</div><span class="sp"></span><select id="smode" style="height:26px"><option value="schema">Structured output</option><option value="json">JSON mode</option></select></div>
 <textarea id="sch" rows="7" spellcheck="false">{"type":"object","properties":{"answer":{"type":"string"}},"required":["answer"]}</textarea><div id="schmsg" class="muted" style="font-size:12px;margin-top:4px"></div></div>
<div id="tools" class="pgp" style="display:none"></div></div>
<div><div class="pgh"><b>Inputs</b></div><div class="card"><div id="vars" class="muted">Add {{variable}} to a message to create an input.</div></div><div class="pgh" style="margin-top:14px"><b>Output</b></div><div id="outs"></div></div></div>
<div class="bodyx nx"><div class="toolbar"><div class="h4">New Experiment</div><span class="muted">Run the prompt over several inputs at once.</span><span class="sp"></span><button class="g" id="nxadd">${plus}Row</button><button class="g" id="nxds">Load dataset</button><button id="nxrun">Run all</button></div><div class="card" style="padding:0"><table><thead><tr><th style="width:34%">Inputs</th><th style="width:28%">Reference Outputs</th><th>Outputs</th><th style="width:30px"></th></tr></thead><tbody id="nxb"></tbody></table></div></div>""".replace("${plus}", '<svg class="ic"><use href="#i-plus"/></svg>')

JS = r"""
let MODELS=[],PRESETS=[],CAT=[],COLS=[{model:'gemini-3.6-flash',preset:null}],TEMP=0.3,PARAMS={max_tokens:'',top_p:'',reasoning_effort:''},LOADED=null,EXTRA=[];
let MSGS=[{role:'system',content:'You are a helpful assistant.',images:[]},{role:'human',content:'{{question}}',images:[]}],VARS={question:'What is LangGraph?'};
let TOOLS=[],TMODE='mock',TCHOICE='auto',TOOLS_ON=false,SCH_ON=false;
const jtry=s=>{try{return [JSON.parse(s),null]}catch(e){return [null,e.message]}};
function hdrDraw(){$('ph').innerHTML=hdr('flask-conical','Playground',LOADED?`<span class="chip">${esc(LOADED.name)} v${LOADED.version}</span>`:'',`<button class="g" id="mcfg">${ICN('settings')}Model Configuration</button><button class="g" id="cmpc">${ICN('plus')}Compare</button><button class="g" id="savep">${ICN('save')}Save</button><button class="g" id="evb">${ICN('gauge')}Set up Evaluation</button><button id="run">${ICN('play')}Start</button>`);
 $('run').onclick=()=>run(false);$('cmpc').onclick=()=>{if(COLS.length>=4)return flash('Up to 4 models',1);const c=PRESETS[COLS.length%Math.max(PRESETS.length,1)];COLS.push(c&&COLS.length<=PRESETS.length?{model:c.model,preset:c.name}:{model:MODELS.find(m=>!COLS.some(x=>x.model===m&&!x.preset))||COLS[0].model,preset:null});outs()};$('mcfg').onclick=cfg;$('savep').onclick=save;$('evb').onclick=evalSetup}
/* ---- messages (+ images) ---- */
function msgs(){$('msgs').innerHTML=MSGS.map((m,i)=>`<div class="msgc"><div class="mh2"><select data-r="${i}" style="height:26px">${['system','human','ai'].map(r=>`<option value="${r}" ${r===m.role?'selected':''}>${r==='human'?'Human':r==='ai'?'AI':'System'}</option>`).join('')}</select><span class="sp"></span>${m.role==='human'?`<button class="gh" data-img="${i}" title="Attach image">${ICN('paperclip')}</button><input type="file" accept="image/png,image/jpeg,image/webp,image/gif" multiple hidden data-file="${i}">`:''}<button class="gh" data-del="${i}">${ICN('trash')}</button></div><textarea data-m="${i}">${esc(m.content)}</textarea>
  ${(m.images||[]).length?`<div class="thumbs">${m.images.map((im,k)=>`<div class="thumb"><img src="data:${im.mime};base64,${im.b64}" alt="${esc(im.name)}" title="${esc(im.name)}"><button class="g" data-rmi="${i}:${k}">${ICN('x')}</button></div>`).join('')}</div>`:''}</div>`).join('');
 $('msgs').querySelectorAll('[data-m]').forEach(t=>t.oninput=()=>{MSGS[+t.dataset.m].content=t.value;vars()});$('msgs').querySelectorAll('[data-r]').forEach(s=>s.onchange=()=>{MSGS[+s.dataset.r].role=s.value;msgs()});
 $('msgs').querySelectorAll('[data-del]').forEach(b=>b.onclick=()=>{MSGS.splice(+b.dataset.del,1);msgs()});
 $('msgs').querySelectorAll('[data-img]').forEach(b=>b.onclick=()=>$('msgs').querySelector(`[data-file="${b.dataset.img}"]`).click());
 $('msgs').querySelectorAll('[data-file]').forEach(f=>f.onchange=async()=>{const m=MSGS[+f.dataset.file];for(const file of f.files){if((m.images||[]).length>=8){flash('At most 8 images per run',1);break}if(file.size>5*1024*1024){flash('Image larger than 5 MB',1);continue}
   const b64=await new Promise(r=>{const rd=new FileReader();rd.onload=()=>r(String(rd.result).split(',')[1]);rd.readAsDataURL(file)});(m.images=m.images||[]).push({name:file.name,mime:file.type,b64})}msgs()});
 $('msgs').querySelectorAll('[data-rmi]').forEach(b=>b.onclick=()=>{const [i,k]=b.dataset.rmi.split(':').map(Number);MSGS[i].images.splice(k,1);msgs()});vars()}
function vars(){const names=[...new Set(MSGS.flatMap(m=>[...m.content.matchAll(/\{\{\s*(\w+)\s*\}\}/g)].map(x=>x[1])))];
 $('vars').innerHTML=names.length?names.map(n=>`<label><span class="var">{{${n}}}</span></label><input data-v="${n}" value="${esc(VARS[n]||'')}" style="width:100%">`).join(''):'Add {{variable}} to a message to create an input.';
 $('vars').querySelectorAll('[data-v]').forEach(i=>i.oninput=()=>VARS[i.dataset.v]=i.value)}
/* ---- tools ---- */
const toolName=t=>t.name||(t.key||'').split(':').pop();
function toolsUI(){const p=$('tools');p.innerHTML=`<div class="row"><div class="h4">Tools</div><span class="sp"></span><button class="g s" id="tcat">${ICN('plus')}From catalogue</button><button class="g s" id="tcus">${ICN('plus')}Custom tool</button></div>
 ${TOOLS.length?TOOLS.map((t,i)=>`<div class="tcard"><div class="row">${ICN('wrench')}<b class="mono">${esc(toolName(t))}</b>${t.key?`<span class="chip ${t.read_only?'ok':'wn'}">${t.read_only?'read-only':'write'}</span>`:`<span class="chip">custom</span>`}<span class="sp"></span><button class="gh" data-trm="${i}">${ICN('x')}</button></div>
   <div class="muted" style="font-size:12px">${esc(t.description||'')}</div><label>Mock result (optional)</label><textarea rows="2" data-mock="${i}" placeholder="What the tool returns">${esc(t.mock||'')}</textarea></div>`).join(''):`<div class="muted" style="margin:8px 0">Attach tools the model may call. Pick from the catalogue or define one with a JSON schema.</div>`}
 <div class="row" style="margin-top:8px"><label style="margin:0">Tool results</label><select id="tmode" style="height:26px"><option value="mock">Mock results only</option><option value="real">Run read-only tools for real</option></select><label style="margin:0">Tool choice</label><select id="tch" style="height:26px"><option value="auto">Auto</option><option value="any">Always call a tool</option><option value="none">Never call a tool</option></select></div>
 <div class="muted" style="font-size:12px;margin-top:6px">Write tools are never executed in the Playground; they only get a mock result.</div>`;
 $('tmode').value=TMODE;$('tch').value=TCHOICE;$('tmode').onchange=e=>TMODE=e.target.value;$('tch').onchange=e=>TCHOICE=e.target.value;
 p.querySelectorAll('[data-mock]').forEach(t=>t.oninput=()=>TOOLS[+t.dataset.mock].mock=t.value);p.querySelectorAll('[data-trm]').forEach(b=>b.onclick=()=>{TOOLS.splice(+b.dataset.trm,1);toolsUI()});
 $('tcat').onclick=catPane;$('tcus').onclick=customPane}
async function catPane(){if(!CAT.length){try{CAT=await api('api/playground/tools')}catch(e){return flash(e.message,1)}}
 pane('Tool catalogue',`<input id="tq" placeholder="Search tools…" style="width:100%"><div class="card" style="padding:0;margin-top:10px;max-height:62vh;overflow:auto">${CAT.map((c,i)=>`<label class="cm" style="align-items:flex-start;font-weight:400"><input type="checkbox" data-ci="${i}" ${TOOLS.some(t=>t.key===c.key)?'checked':''}><div style="flex:1;min-width:0"><div class="row"><b class="mono">${esc(c.name)}</b><span class="chip ${c.read_only?'ok':'wn'}">${c.read_only?'read-only':'write'}</span></div><div class="muted" style="font-size:12px">${esc(c.description||'')}</div></div></label>`).join('')}</div>
  <div class="row" style="margin-top:12px"><span class="sp"></span><button id="tdone">Done</button></div>`,p=>{
  p.querySelector('#tq').oninput=e=>{const q=e.target.value.toLowerCase();p.querySelectorAll('[data-ci]').forEach(c=>{const x=CAT[+c.dataset.ci];c.closest('label').style.display=(x.key+' '+x.description).toLowerCase().includes(q)?'':'none'})};
  p.querySelector('#tdone').onclick=()=>{p.querySelectorAll('[data-ci]').forEach(c=>{const x=CAT[+c.dataset.ci],at=TOOLS.findIndex(t=>t.key===x.key);if(c.checked&&at<0)TOOLS.push({key:x.key,name:x.name,description:x.description,read_only:x.read_only,mock:''});if(!c.checked&&at>=0)TOOLS.splice(at,1)});closePane();toolsUI()}})}
function customPane(){pane('Custom tool',`<label>Name</label><input id="cn_" style="width:100%" placeholder="get_weather"><label>Description</label><input id="cd_" style="width:100%" placeholder="What the tool does">
  <label>Parameters (JSON schema)</label><textarea id="cp_" rows="9" style="width:100%;font-family:var(--mono);font-size:12px">{"type":"object","properties":{"city":{"type":"string"}},"required":["city"]}</textarea>
  <div class="row" style="margin-top:12px"><span class="sp"></span><button id="cok_">Add tool</button></div>`,p=>{p.querySelector('#cok_').onclick=()=>{const n=p.querySelector('#cn_').value.trim(),[pr,er]=jtry(p.querySelector('#cp_').value);
   if(!/^[A-Za-z_][\w-]{0,63}$/.test(n))return flash('Tool name: letters, digits, _ and - only',1);if(er)return flash('Parameters are not valid JSON',1);
   TOOLS.push({name:n,description:p.querySelector('#cd_').value,parameters:pr,mock:''});closePane();toolsUI()}})}
/* ---- output ---- */
const cfgKey=c=>c.preset?'p:'+c.preset:'m:'+c.model;
function stepHtml(s,old){if(s.type==='model')return s.message.content?`<div class="stp ${old?'old':''}">${esc(s.message.content)}</div>`:'';
 const src={mock:['Mock result','ok'],real:['Real result','pu'],pending:['Waiting for a result','wn'],error:['Error','er']}[s.source]||[s.source,''];
 return `<div class="tcard ${old?'old':''}"><div class="row">${ICN('wrench')}<b class="mono">${esc(s.name)}</b><span class="chip ${src[1]}">${src[0]}</span></div><pre>${esc(JSON.stringify(s.args,null,2))}</pre>
  ${(s.args_errors||[]).map(e=>`<div class="errl">${esc(e.path)}: ${esc(e.message)}</div>`).join('')}${s.result!=null?`<pre>${esc(s.result)}</pre>`:''}
  ${s.source==='pending'?`<div class="muted" style="font-size:12px;margin-top:4px">${s.reason==='needs_approval'?'Write tool: it is not executed here. Type the result it would return.':'Type the result this tool should return.'}</div><textarea rows="2" data-pend="${esc(s.id)}" placeholder="Tool result"></textarea>`:''}</div>`}
function structHtml(s){return `<div class="row" style="margin:8px 0 4px"><span class="chip ${s.valid?'ok':'er'}">${ICN(s.valid?'circle-check':'circle-alert')}${s.valid?'Valid JSON for the schema':'Does not match the schema'}</span><span class="chip">${s.mode==='json'?'JSON mode':'Structured output'}</span></div>
  ${s.errors.map(e=>`<div class="errl"><span style="font-family:var(--mono)">${esc(e.path)}</span> ${esc(e.message)}</div>`).join('')}<pre style="max-height:260px;overflow:auto">${esc(s.parsed!=null?JSON.stringify(s.parsed,null,2):s.raw||'')}</pre>`}
function modelSel(){const c0=COLS[0],ms=[...new Set([c0.model,...MODELS])];$('pmodel').innerHTML=c0.preset?`<option>${esc(c0.preset)} · ${esc(c0.model)}</option>`:ms.map(m=>`<option ${m===c0.model?'selected':''}>${m}</option>`).join('');$('pmodel').disabled=!!c0.preset}
function outs(){modelSel();const opt=c=>`<optgroup label="Saved configurations">${PRESETS.map(p=>`<option value="p:${esc(p.name)}" ${cfgKey(c)==='p:'+p.name?'selected':''}>${esc(p.name)}</option>`).join('')}</optgroup><optgroup label="Models">${MODELS.map(m=>`<option value="m:${m}" ${cfgKey(c)==='m:'+m?'selected':''}>${m}</option>`).join('')}</optgroup>`;
 $('outs').innerHTML=COLS.map((c,i)=>{const r=c.res;return `<div class="card" style="margin-bottom:12px"><div class="row"><select data-c="${i}" style="height:28px">${opt(c)}</select><span class="sp"></span>${r?`${latPill(r.ms)}<span class="chip">${ICN('coins')}${fmtN((r.input_tokens||0)+(r.output_tokens||0))} / $${Number(r.cost_usd||0).toFixed(5)}</span>${r.run_id?`<a href="projects?trace=${r.run_id}" title="Open trace">${ICN('external-link')}</a>`:''}`:''}${COLS.length>1?`<button class="gh" data-rm="${i}">${ICN('x')}</button>`:''}</div>
  ${r&&r.config?`<div class="row" style="gap:6px;margin-top:8px"><span class="chip mono">${esc(r.model)}</span>${r.config.temperature!=null?`<span class="chip mono">t=${r.config.temperature}</span>`:''}${r.config.max_tokens?`<span class="chip mono">max ${r.config.max_tokens}</span>`:''}${r.config.top_p!=null?`<span class="chip mono">top_p ${r.config.top_p}</span>`:''}${r.config.reasoning_effort?`<span class="chip mono">effort ${esc(r.config.reasoning_effort)}</span>`:''}</div>`:''}
  <div class="h4" style="margin:10px 0 4px">Output</div><div style="min-height:80px">${c.busy?`<span class="muted">${ICN('loader')} Running…</span>`:r?(r.error&&!r.steps.length?`<span class="err">${esc(r.error)}</span>`:`${(c.prev||[]).map(s=>stepHtml(s,true)).join('')}${r.steps.map(s=>stepHtml(s)).join('')}${r.structured?structHtml(r.structured):''}${r.error?`<div class="errl">${esc(r.error)}</div>`:''}
   ${r.pending&&r.pending.length&&COLS.length===1?`<div class="row" style="margin-top:8px"><span class="sp"></span><button id="pcont">${ICN('play')}Send results and continue</button></div>`:''}`):'<span class="muted">Press Start to run the prompt.</span>'}</div></div>`}).join('');
 $('outs').querySelectorAll('[data-c]').forEach(s=>s.onchange=()=>{const c=COLS[+s.dataset.c],[k,v]=[s.value.slice(0,1),s.value.slice(2)];if(k==='p'){const p=PRESETS.find(x=>x.name===v);c.preset=v;c.model=p?p.model:c.model}else{c.preset=null;c.model=v}outs()});
 $('outs').querySelectorAll('[data-rm]').forEach(b=>b.onclick=()=>{COLS.splice(+b.dataset.rm,1);outs()});const pc=$('pcont');if(pc)pc.onclick=cont}
/* ---- run ---- */
const imgOf=im=>({type:'image',base64:im.b64,mime_type:im.mime});
const msgPayload=m=>(m.images&&m.images.length)?{role:m.role,content:[{type:'text',text:m.content},...m.images.map(imgOf)]}:{role:m.role,content:m.content};
const tpl=()=>MSGS.map(m=>(m.role==='system'?'':m.role==='ai'?'AI: ':'')+m.content).join('\n\n');
function body(){const b={messages:[...MSGS.map(msgPayload),...EXTRA],variables:VARS,prompt_ref:LOADED?LOADED.name+':'+LOADED.version:null,
  configs:COLS.map(c=>c.preset?{preset:c.preset}:{model:c.model,temperature:TEMP,...(+PARAMS.max_tokens?{max_tokens:+PARAMS.max_tokens}:{}),...(PARAMS.top_p!==''?{top_p:+PARAMS.top_p}:{}),...(PARAMS.reasoning_effort?{reasoning_effort:PARAMS.reasoning_effort}:{})})};
 if(TOOLS_ON&&TOOLS.length){b.tools=TOOLS.map(t=>t.key?{key:t.key}:{name:t.name,description:t.description,parameters:t.parameters});b.tools_run=TMODE;b.tool_choice=TCHOICE==='auto'?null:TCHOICE;b.mock_results={};
  TOOLS.filter(t=>(t.mock||'').trim()).forEach(t=>{const [j]=jtry(t.mock);b.mock_results[toolName(t)]=j!==null?j:t.mock})}
 if(SCH_ON){const [s,er]=jtry($('sch').value);if(er)throw new Error('Output schema is not valid JSON');b.structured={mode:$('smode').value,schema:s}}return b}
async function run(keep){if(!keep){EXTRA=[];COLS.forEach(c=>c.prev=[])}let b;try{b=body()}catch(e){return flash(e.message,1)}COLS.forEach(c=>{c.busy=true;c.res=null});outs();
 try{const r=await api('api/playground/lab','POST',b);r.results.forEach((x,i)=>COLS[i].res=x)}catch(e){flash(e.message,1)}COLS.forEach(c=>c.busy=false);outs()}
async function cont(){const c=COLS[0],r=c.res;if(!r||!r.pending.length)return;const add=[...r.appended],typed={};
 for(const p of r.pending){const t=document.querySelector(`[data-pend="${p.id}"]`),v=(t&&t.value.trim())||'(no result)';typed[p.id]=v;add.push({role:'tool',tool_call_id:p.id,name:p.name,content:v})}
 c.prev=(c.prev||[]).concat(r.steps.map(s=>s.source==='pending'?{...s,source:'mock',result:typed[s.id]}:s));EXTRA=EXTRA.concat(add);await run(true)}
/* ---- model configurations (saved presets) ---- */
async function loadPresets(){try{PRESETS=await api('api/model_presets')}catch(e){PRESETS=[]}}
function cfg(){const c0=COLS[0],pr=PRESETS.find(p=>p.name===c0.preset);
 pane('Model Configuration',`<label>Saved configuration</label><div class="row"><select id="cpre" style="flex:1"><option value="">– none –</option>${PRESETS.map(p=>`<option value="${esc(p.name)}" ${p.name===c0.preset?'selected':''}>${esc(p.name)}</option>`).join('')}</select><button class="g s" id="cdel" ${pr?'':'disabled'}>${ICN('trash')}Delete</button><button class="g s" id="cclone" ${pr?'':'disabled'}>Clone</button><button class="g s" id="cdflt" ${pr&&!pr.is_default?'':'disabled'}>${pr&&pr.is_default?'Default configuration':'Set default'}</button></div>
  <div class="muted" style="font-size:12px;margin:4px 0 10px">Pick one to use it, or set the values below and save them as a new configuration.</div>
  <label>Provider</label><input value="${esc(pr&&pr.provider||'Google Gemini')}" disabled style="width:100%"><label>Model</label><select id="cm" style="width:100%">${[...new Set([c0.model,...MODELS])].map(m=>`<option ${m===c0.model?'selected':''}>${m}</option>`).join('')}</select>
  <label>Temperature: <b id="tv">${pr&&pr.temperature!=null?pr.temperature:TEMP}</b></label><input id="ct" type="range" min="0" max="2" step="0.1" value="${pr&&pr.temperature!=null?pr.temperature:TEMP}" style="width:100%">
  <div class="row"><div style="flex:1"><label>Max tokens</label><input id="cmx" type="number" min="1" max="65536" placeholder="Default" value="${pr&&pr.max_tokens||PARAMS.max_tokens||''}" style="width:100%"></div><div style="flex:1"><label>Top P</label><input id="ctp" type="number" min="0" max="1" step="0.05" placeholder="Default" value="${pr&&pr.top_p!=null?pr.top_p:PARAMS.top_p}" style="width:100%"></div>
  <div style="flex:1"><label>Reasoning effort</label><select id="cre" style="width:100%">${[['','Default'],['minimal','Minimal'],['low','Low'],['medium','Medium'],['high','High']].map(([x,l])=>`<option value="${x}" ${x===(pr&&pr.reasoning_effort||PARAMS.reasoning_effort||'')?'selected':''}>${l}</option>`).join('')}</select></div></div>
  <div class="row" style="margin-top:14px"><input id="cname" placeholder="Name for a new configuration" style="flex:1"><button class="g" id="csave">${ICN('save')}Save as configuration</button></div>
  <div class="row" style="margin-top:14px"><span class="sp"></span><button id="cs">Use</button></div>`,p=>{
  const vals=()=>({model:p.querySelector('#cm').value,temperature:+p.querySelector('#ct').value,max_tokens:+p.querySelector('#cmx').value||null,top_p:p.querySelector('#ctp').value===''?null:+p.querySelector('#ctp').value,reasoning_effort:p.querySelector('#cre').value||null});
  p.querySelector('#ct').oninput=e=>p.querySelector('#tv').textContent=e.target.value;
  p.querySelector('#cpre').onchange=e=>{const x=PRESETS.find(q=>q.name===e.target.value);if(x){c0.preset=x.name;c0.model=x.model}else c0.preset=null;closePane();outs();cfg()};
  p.querySelector('#cdel').onclick=async()=>{if(!pr||!confirm('Delete this configuration?'))return;try{await api('api/model_presets/'+pr.id,'DELETE');await loadPresets();COLS.forEach(c=>{if(c.preset===pr.name)c.preset=null});closePane();outs()}catch(e){flash(e.message,1)}};
  p.querySelector('#cclone').onclick=async()=>{if(!pr)return;try{const r=await api('api/model_configs/'+pr.id+'/clone','POST',{});await loadPresets();c0.preset=r.name;c0.model=r.model;flash('Configuration saved');closePane();outs()}catch(e){flash(e.message,1)}};
  p.querySelector('#cdflt').onclick=async()=>{if(!pr)return;try{await api('api/model_configs/'+pr.id+'/default','PUT');await loadPresets();flash('Configuration saved');closePane();outs()}catch(e){flash(e.message,1)}};
  p.querySelector('#csave').onclick=async()=>{const n=p.querySelector('#cname').value.trim();if(!/^[\w\-. ]{1,60}$/.test(n))return flash('Give the configuration a name (letters, digits, - . _ and spaces)',1);const v=vals();
   try{await api('api/model_presets','POST',{name:n,...v});await loadPresets();c0.preset=n;c0.model=v.model;flash('Configuration saved');closePane();outs()}catch(e){flash(e.message,1)}};
  p.querySelector('#cs').onclick=()=>{if(!c0.preset||p.querySelector('#cpre').value===''){const v=vals();c0.preset=null;c0.model=v.model;TEMP=v.temperature;PARAMS={max_tokens:v.max_tokens||'',top_p:v.top_p==null?'':v.top_p,reasoning_effort:v.reasoning_effort||''}}closePane();outs()}})}
/* ---- save as prompt / evaluation / experiment (as before) ---- */
async function save(){const n=prompt('Prompt name',LOADED?LOADED.name:'my-prompt');if(!n)return;const msg=prompt('Commit message','')||null;try{const r=await api('api/hub/commit','POST',{name:n,template:tpl(),model:COLS[0].model,temperature:TEMP,variables:VARS,message:msg});flash(`Committed ${n} v${r.version}`);LOADED={name:n,version:r.version,id:r.id};hdrDraw()}catch(e){flash(e.message,1)}}
async function evalSetup(){if(!LOADED)return flash('Save the prompt first',1);const [ds,ev]=await Promise.all([api('api/datasets'),api('api/evaluators')]);
 pane('Set up Evaluation',`<label>Dataset</label><select id="ed" style="width:100%">${ds.map(d=>`<option value="${d.id}">${esc(d.name)} (${d.n})</option>`).join('')}</select><label>Evaluators</label>${ev.map(e=>`<label style="display:flex;gap:6px;font-weight:400"><input type="checkbox" class="ee" value="${e.id}">${esc(e.name)}</label>`).join('')}
 <div class="row" style="margin-top:14px"><span class="sp"></span><button id="ego">${ICN('play')}Start</button></div>`,p=>{p.querySelector('#ego').onclick=async()=>{const r=await api('api/playground/batch','POST',{prompt_id:LOADED.id,version:LOADED.version,dataset_id:+p.querySelector('#ed').value,model:COLS[0].model,evaluator_ids:[...p.querySelectorAll('.ee:checked')].map(c=>+c.value)});closePane();flash('Experiment #'+r.experiment_id+' started')}})}
let NX=[{inputs:'{"question": "What is LangGraph?"}',ref:'',out:''}];
function nx(){$('nxb').innerHTML=NX.map((r,i)=>`<tr><td><textarea data-ni="${i}">${esc(r.inputs)}</textarea></td><td><textarea data-nr="${i}">${esc(r.ref)}</textarea></td><td style="white-space:pre-wrap;font-size:13px">${r.busy?`<span class="muted">${ICN('loader')} Running…</span>`:esc(r.out||'')}</td><td><button class="gh" data-nd="${i}">${ICN('x')}</button></td></tr>`).join('');
 $('nxb').querySelectorAll('[data-ni]').forEach(t=>t.oninput=()=>NX[+t.dataset.ni].inputs=t.value);$('nxb').querySelectorAll('[data-nr]').forEach(t=>t.oninput=()=>NX[+t.dataset.nr].ref=t.value);$('nxb').querySelectorAll('[data-nd]').forEach(b=>b.onclick=()=>{NX.splice(+b.dataset.nd,1);nx()})}
$('nxadd').onclick=()=>{NX.push({inputs:'{}',ref:'',out:''});nx()};
$('nxds').onclick=async()=>{const ds=await api('api/datasets');pane('Load dataset',`<select id="ldd" style="width:100%">${ds.map(d=>`<option value="${d.id}">${esc(d.name)} (${d.n})</option>`).join('')}</select><div class="row" style="margin-top:14px"><span class="sp"></span><button id="ldo">Load</button></div>`,p=>{p.querySelector('#ldo').onclick=async()=>{const d=await api('api/datasets/'+p.querySelector('#ldd').value);NX=d.examples.slice(0,50).map(e=>({inputs:JSON.stringify(e.inputs),ref:e.outputs?JSON.stringify(e.outputs):'',out:''}));closePane();nx()}})};
$('nxrun').onclick=async()=>{for(const r of NX){let v;try{v=JSON.parse(r.inputs||'{}')}catch(e){r.out='Inputs must be JSON';continue}r.busy=true;nx();try{const x=await api('api/playground/multi','POST',{template:tpl(),variables:v,models:[COLS[0].model],temperature:TEMP});const o=x.results[0];r.out=o.error||o.output||''}catch(e){r.out=e.message}r.busy=false;nx()}};
$('addt').onclick=()=>{TOOLS_ON=!TOOLS_ON;$('tools').style.display=TOOLS_ON?'block':'none';if(TOOLS_ON)toolsUI()};
$('addm').onclick=()=>{MSGS.push({role:'human',content:'',images:[]});msgs()};
$('adds').onclick=()=>{SCH_ON=!SCH_ON;$('schema').style.display=SCH_ON?'block':'none'};
$('sch').oninput=()=>{const [,er]=jtry($('sch').value);$('schmsg').innerHTML=er?`<span class="err">${esc(er)}</span>`:''};
(async()=>{MODELS=await api('api/gw/catalog?feature=playground').then(c=>c.models.filter(x=>x.type==='model').map(x=>x.id)).catch(()=>api('api/models').then(m=>Array.isArray(m)?m:(m.models||[]))).catch(()=>['gemini-3.6-flash']);if(!MODELS.length)MODELS=['gemini-3.6-flash'];await loadPresets();COLS[0].model=MODELS.includes('gemini-3.6-flash')?'gemini-3.6-flash':MODELS[0];
 if(QS.get('prompt')){const d=await api('api/hub/'+QS.get('prompt'));const v=d.versions.find(x=>x.version==QS.get('version'))||d.versions[0];MSGS=[{role:'human',content:v.template,images:[]}];VARS=v.variables||{};TEMP=v.temperature;if(MODELS.includes(v.model))COLS[0].model=v.model;LOADED={name:d.prompt.name,version:v.version,id:d.prompt.id};
  if(v.output_schema){SCH_ON=true;$('schema').style.display='block';$('sch').value=JSON.stringify(v.output_schema,null,2)}}
 $('pmodel').onchange=e=>{COLS[0].model=e.target.value;COLS[0].preset=null;outs()};
 hdrDraw();msgs();outs();nx()})();
"""

PLAYGROUND = page("playground", "Playground", BASE_CSS + CSS + BODY, HELP_JS + JS)
